import { grammarTopics } from './grammar_content.mjs';
import { escapeAudio as e, registerAudioLesson, renderLessonAudio } from './lesson_audio.mjs';
let selected='',stage='全部';
const answers={};
for(const t of grammarTopics)registerAudioLesson('grammar:'+t.id,t.title,[{title:'核心觀念',text:t.rule},...t.rows.map(r=>({title:r[0],text:r.slice(1).join('。')})),{title:'易錯提醒',text:t.trap},{title:'回想練習',text:'想一想。'+t.question+'。選項：'+t.options.join('。'),recall:true},{title:'答案與解釋',text:'答案是：'+t.options[t.answer]+'。'+t.explanation}]);
export function setGrammarTopic(id=''){selected=grammarTopics.some(t=>t.id===id)?id:'';}
export function grammarRoute(){return '#grammar'+(selected?'/'+selected:'');}
function table(headers,rows,caption){return `<div class="grammar-table" tabindex="0" role="region" aria-label="${e(caption)}"><table><caption>${e(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>`<${i?'td':'th scope="row"'}>${e(cell)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const timeline=`<figure class="grammar-timeline"><div aria-hidden="true">過去 ◀━━━━━━ <strong>現在 ●</strong> ━━━━━━▶ 未來</div><figcaption>時態先找「參照時間」，再看動作是一般、進行、完成，或完成進行。</figcaption></figure>`;
const tenseRows=[['現在','work / works','am/is/are working','have/has worked','have/has been working'],['過去','worked','was/were working','had worked','had been working'],['未來表達','will work','will be working','will have worked','will have been working']];
const sources=`<details class="card"><summary>教學設計與參考來源</summary><p>本站以原創繁中說明與例句整理核心文法；學段為學習建議，不代表各校教材進度一致。</p><ul><li><a href="https://learnenglish.britishcouncil.org/grammar/english-grammar-reference" target="_blank" rel="noreferrer">British Council：英文文法參考</a></li><li><a href="https://learnenglish.britishcouncil.org/free-resources/grammar/b1-b2/passives" target="_blank" rel="noreferrer">British Council：被動語態</a></li><li><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noreferrer">IES：圖文整合、例題與主動回想</a></li></ul></details>`;
export function grammarPage(){
 const t=grammarTopics.find(x=>x.id===selected);
 if(t){const result=answers[t.id];return `<article class="lesson-page grammar-detail"><a href="#grammar">← 文法總覽</a><header><p class="pill">${t.icon} ${t.stage} · 圖解文法</p><h1>${e(t.title)}</h1><p>${e(t.rule)}</p></header>${renderLessonAudio('grammar:'+t.id)}<section class="card"><h2>看圖抓住判斷順序</h2><ol class="grammar-flow">${t.flow.map(step=>`<li>${e(step)}</li>`).join('')}</ol>${['present-past','progressive','perfect','future'].includes(t.id)?timeline:''}${table(t.headers,t.rows,t.title+'對照表')}<aside class="lesson-tip"><strong>⚠ 易錯提醒</strong><p>${e(t.trap)}</p></aside></section><section class="card"><h2>不看表格，自己判斷</h2><fieldset><legend>${e(t.question)}</legend><div class="grammar-choices">${t.options.map((option,i)=>`<button class="btn ${result===i?'primary':'quiet'}" data-grammar-answer="${t.id}" data-grammar-choice="${i}" aria-pressed="${result===i}">${String.fromCharCode(65+i)}. ${e(option)}</button>`).join('')}</div></fieldset><div role="status">${result!==undefined?`<p><strong>${result===t.answer?'✓ 答對了':'再想想，這裡需要訂正'}</strong> · 正解：${e(t.options[t.answer])}</p><p>${e(t.explanation)}</p><button class="btn quiet" data-grammar-retry="${t.id}">再練一次</button>`:''}</div><h3>換個情境使用</h3><p>把對照表的一句改成自己的生活、校園或工作情境。核對主詞、動詞形式與意思，再隔天不看表重說一次。</p></section><nav class="lesson-links"><a href="#grammar">回文法總覽</a>${grammarTopics[grammarTopics.indexOf(t)+1]?`<a href="#grammar/${grammarTopics[grammarTopics.indexOf(t)+1].id}">下一主題 →</a>`:''}</nav>${sources}</article>`;}
 const filtered=grammarTopics.filter(t=>stage==='全部'||t.stage===stage);
 return `<header class="header-block"><div class="pill">🧩 英文文法專區</div><h1>先看全貌，再把一句話弄懂</h1><p>20 個核心主題，用句型圖、時間軸與對照表串起國小、國中、高中／高工文法。每一課都可以聽、看例子，再做一次理解檢核。</p><a class="btn" href="#listening">🎧 通勤聽課教室</a></header>
 <section class="card"><h2>一張地圖，看懂文法在做什麼</h2><ol class="grammar-flow"><li>🧱 誰＋做什麼<br>主詞、動詞、句型</li><li>📦 說清楚人事物<br>名詞、代名詞、修飾語</li><li>🕒 說明時間與態度<br>時態、情態、被動</li><li>🧩 連起多個想法<br>子句、假設、分詞</li></ol><div class="sentence-map" role="img" aria-label="The technician 是主詞；checked 是過去式動詞；the cable 是受詞；carefully 是修飾動作的副詞。"><span>👤 The technician<small>主詞：誰</small></span><span>⚙ checked<small>動詞：做什麼／過去</small></span><span>📦 the cable<small>受詞：動作對象</small></span><span>🎯 carefully<small>副詞：怎麼做</small></span></div><p>先確認句子完整，再添加時間、地點、原因。顏色只用來輔助分組，每個區塊都有文字標籤。</p></section>
 <section class="card"><h2>依學習階段選擇路線</h2>${table(['路線','建議順序','學會後試做'],[['國小','句子骨架 → be / do → 名詞 → 代名詞 → 介系詞','介紹自己、問時間、描述日常。'],['國中','修飾語 → 時態 → 情態 → 不定詞與動名詞','敘述事件、比較事物、說明計畫。'],['高中／高工','被動 → 各類子句 → 假設 → 分詞 → 一致與倒裝','讀懂長句、寫流程與維修紀錄。']],'文法學習路線')}<div class="audio-controls">${['全部','國小','國中','高中／高工'].map(s=>`<button class="btn ${stage===s?'primary':'quiet'}" data-grammar-stage="${s}" aria-pressed="${stage===s}">${s}</button>`).join('')}</div><div class="grammar-grid">${filtered.map(t=>`<a class="knowledge-card" href="#grammar/${t.id}"><span class="pill">${t.icon} ${t.stage}</span><h3>${e(t.title)}</h3><p>${e(t.rule)}</p><span>圖解・對照表・語音・檢核 →</span></a>`).join('')}</div></section>
 <section class="card"><h2>時態全貌：時間 × 動作樣貌</h2>${timeline}${table(['參照時間','一般','進行','完成','完成進行'],tenseRows,'常見時態形式對照（以 work 為例）')}<p>一般：習慣／事實／事件。進行：參照點附近正在做。完成：先前事件與參照點有關。完成進行：強調延續活動及其過程。未來也可用 going to、現在進行式與時刻表用法，不只 will。</p><p>例：I have been working for two hours. 我已連續工作兩小時，強調活動的延續。先掌握常用形式，再學較少見的未來完成進行式。</p><div class="audio-controls"><a class="btn" href="#grammar/present-past">現在／過去</a><a class="btn" href="#grammar/progressive">進行式</a><a class="btn" href="#grammar/perfect">完成式</a><a class="btn" href="#grammar/future">未來表達</a></div></section>${sources}`;
}
export function handleGrammarClick(button,render){const d=button.dataset;if(d.grammarStage){if(['全部','國小','國中','高中／高工'].includes(d.grammarStage)){stage=d.grammarStage;render();}return true;}if(d.grammarAnswer){const t=grammarTopics.find(t=>t.id===d.grammarAnswer),choice=Number(d.grammarChoice);if(t&&Number.isInteger(choice)&&choice>=0&&choice<t.options.length){answers[t.id]=choice;render();}return true;}if(d.grammarRetry){delete answers[d.grammarRetry];render();return true;}return false;}
